import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { format, resolveConfig } from 'prettier';
import { runtimeInventory } from './runtime-inventory.mjs';

export async function buildRuntimeManifest() {
  const inventory = await runtimeInventory();
  const selected = inventory.assets.filter(
    (row) =>
      !row.roles.includes('unused-decoded-diffuse') &&
      !(row.roles.length === 1 && row.roles[0] === 'startup-glob'),
  );
  const lines = [
    '// Generated by scripts/assets/runtime-manifest.mjs. Do not edit by hand.',
    'export const runtimeAssets = [',
  ];
  for (const row of selected) {
    const url = path.posix.relative('src/platform', row.path);
    const group = row.path.startsWith('src/rendering/environment/')
      ? 'environment'
      : row.path.startsWith('src/rendering/figures/')
        ? 'figures'
        : 'ui';
    lines.push(
      `{ url: new URL(${JSON.stringify(url)}, import.meta.url).href, width: ${row.width}, height: ${row.height}, group: ${JSON.stringify(group)}, stages: ${JSON.stringify(row.stages)} },`,
    );
  }
  lines.push('] as const;', '');
  return format(lines.join('\n'), {
    ...(await resolveConfig('src/platform/runtime-assets.ts')),
    filepath: 'src/platform/runtime-assets.ts',
  });
}
export async function generateRuntimeManifest() {
  const output = await buildRuntimeManifest();
  await writeFile('src/platform/runtime-assets.ts', output);
  return output;
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  await generateRuntimeManifest();
